actions.script:
allowed = true
if (!ec.user.isInGroup('ADMIN')) {
    def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
    if (!activeOrg || activeOrg == '_NA_') {
        allowed = false
    } else {
        def p = ec.entity.find('mantle.party.Party').condition('partyId', partyId).disableAuthz().one()
        if (p == null || p.ownerPartyId != activeOrg) allowed = false
    }
    if (!allowed) ec.message.addError("You do not have access to this contact.")
}

def g = gstin?.trim()?.toUpperCase()
if (!g || !(g ==~ /[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]/)) {
    ec.message.addError("That GSTIN doesn't look valid. A GSTIN is 15 characters, e.g. 29ABCDE1234F1Z5.")
} else {
    gstin = g
    stateCode = g.substring(0, 2)   // state code is the first two digits of the GSTIN
}

if (contactNumber?.trim()) {
    def digits = contactNumber.trim().replaceAll(/[\s\-().]/, '')
    if (!(digits ==~ /[0-9]{6,15}/)) {
        ec.message.addError("Enter a valid phone number: 6 to 15 digits, no letters.")
    } else { contactNumber = digits }
}
if (countryCode?.trim()) {
    def cc = countryCode.trim().replaceAll(/^\+/, '')
    if (!(cc ==~ /[0-9]{1,4}/)) {
        ec.message.addError("Country code must be 1 to 4 digits (e.g. 91).")
    } else { countryCode = cc }
}

if ((firstName && firstName.trim().length() > 60) || (lastName && lastName.trim().length() > 60))
    ec.message.addError("First and last name can each be at most 60 characters.")
if (organizationName && organizationName.trim().length() > 120)
    ec.message.addError("Business name can be at most 120 characters.")

if (panNumber?.trim()) {
    panNumber = panNumber.trim().toUpperCase()
    if (!(panNumber ==~ /[A-Z]{5}[0-9]{4}[A-Z]/)) {
        ec.message.addError("That PAN doesn't look valid. A PAN is 10 characters, e.g. ABCDE1234F.")
    }
}

def _org = ec.user.getPreference('ACTIVE_ORGANIZATION') ?: '_NA_'
if (contactNumber && allowDuplicate != 'Y' && _org) {
    def matches = ec.entity.find("mantle.party.contact.PartyContactMechTelecomNumber")
        .condition("contactMechPurposeId", "PhonePrimary")
        .condition("contactNumber", contactNumber)
        .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp)
        .disableAuthz().list()
    def dupName = null
    for (row in matches) {
        def pty = ec.entity.find("mantle.party.Party").condition("partyId", row.partyId).disableAuthz().one()
        if (pty == null || pty.ownerPartyId != _org) continue
        def per = ec.entity.find("mantle.party.Person").condition("partyId", row.partyId).disableAuthz().one()
        def nm = per ? ((per.firstName ?: '') + ' ' + (per.lastName ?: '')).trim() : null
        if (!nm) nm = ec.entity.find("mantle.party.Organization").condition("partyId", row.partyId).disableAuthz().one()?.organizationName
        dupName = nm ?: row.partyId
        break
    }
    if (dupName) ec.message.addError("A contact '" + dupName + "' with phone " + contactNumber + " already exists in your account. Edit or merge that contact instead of creating a duplicate.")
}

if (panNumber?.trim()) {
    panNumber = panNumber.trim().toUpperCase()
    if (!(panNumber ==~ /[A-Z]{5}[0-9]{4}[A-Z]/)) {
        ec.message.addError("That PAN doesn't look valid. A PAN is 10 characters, e.g. ABCDE1234F.")
    }
}
if (bankIfscCode?.trim()) bankIfscCode = bankIfscCode.trim().toUpperCase()
// ZE-CONTACTS-021 f/u: cap name lengths (client maxlength not enforced on /qapps)
if ((firstName && firstName.trim().length() > 60) || (lastName && lastName.trim().length() > 60))
    ec.message.addError("First and last name can each be at most 60 characters.")
if (organizationName && organizationName.trim().length() > 120)
    ec.message.addError("Business name can be at most 120 characters.")

if (tdsApplicable != 'Y') defaultTdsSectionId = null
if (!msmeStatusEnumId || msmeStatusEnumId == 'Not Registered') {
    msmeUdyamNumber = null
    paymentTermLockDays = null
}

def refs = []
if (ec.entity.find("mantle.account.invoice.Invoice").condition("toPartyId", partyId).count() +
    ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId", partyId).count() > 0) refs.add("invoices")
if (ec.entity.find("mantle.order.OrderPart").condition("customerPartyId", partyId).count() +
    ec.entity.find("mantle.order.OrderPart").condition("vendorPartyId", partyId).count() > 0) refs.add("orders")
if (ec.entity.find("zenith.erp.pos.PosTransaction").condition("customerPartyId", partyId).count() > 0) refs.add("POS bills")
if (refs) {
    ec.message.addError("Cannot delete: this contact is on " + refs.join(", ") + ". Set the contact to Disabled instead (Edit -> Disabled -> Y).")
    return
}
// audit: an irreversible delete on a live system must be reconstructable from the logs
def _audP = ec.entity.find("mantle.party.Party").condition("partyId", partyId).one()
ec.logger.warn("delete#Contact AUDIT: user " + (ec.user.username ?: "?") + " permanently deleting contact " + partyId + " (org " + (_audP?.ownerPartyId ?: "?") + "): " + groovy.json.JsonOutput.toJson(_audP != null ? new HashMap(_audP) : [:]))
try {
    def pcms = ec.entity.find("mantle.party.contact.PartyContactMech").condition("partyId", partyId).list()
    def cmIds = pcms*.contactMechId.unique()
    ec.entity.find("mantle.party.contact.PartyContactMech").condition("partyId", partyId).deleteAll()
    for (cmId in cmIds) {
        ec.entity.find("mantle.party.contact.TelecomNumber").condition("contactMechId", cmId).deleteAll()
        ec.entity.find("mantle.party.contact.PostalAddress").condition("contactMechId", cmId).deleteAll()
        ec.entity.find("mantle.party.contact.ContactMech").condition("contactMechId", cmId).deleteAll()
    }
    ec.entity.find("zenith.erp.contacts.PartyTag").condition("partyId", partyId).deleteAll()
    ec.entity.find("zenith.erp.contacts.CustomerGroupMember").condition("partyId", partyId).deleteAll()
    ec.entity.find("zenith.erp.tax.TaxRegistration").condition("partyId", partyId).deleteAll()
    ec.entity.find("zenith.erp.india.IndiaGstin").condition("partyId", partyId).deleteAll()
    ec.entity.find("mantle.party.PartyIdentification").condition("partyId", partyId).deleteAll()
    ec.entity.find("mantle.party.PartyRole").condition("partyId", partyId).deleteAll()
    ec.entity.find("mantle.party.Person").condition("partyId", partyId).deleteAll()
    ec.entity.find("mantle.party.Organization").condition("partyId", partyId).deleteAll()
    ec.entity.find("mantle.party.Party").condition("partyId", partyId).deleteAll()
    ec.message.addMessage("Contact deleted.")
} catch (Exception e) {
    ec.logger.warn("delete#Contact blocked for " + partyId + ": " + e.message)
    ec.message.addError("Cannot delete this contact — it is referenced by other records. Set it to Disabled instead (Edit -> Disabled -> Y).")
}

def rn = registrationNumber?.trim()?.toUpperCase()
def isGst = (registrationTypeEnumId == 'TrtGstin' || (taxAuthorityId?.toString()?.contains('GST')))
if (rn &amp;&amp; (isGst || rn.length() == 15)) {
    if (!(rn ==~ /[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]/)) {
        ec.message.addError("That GSTIN doesn't look valid. A GSTIN is 15 characters, e.g. 29ABCDE1234F1Z5.")
    }
}
if (!ec.message.hasError()) registrationNumber = rn

// Move rows whose party field = the duplicate onto the survivor. If that field is part of the
// entity's PK it CAN'T be updated in place (e.g. ShipmentParty.partyId) — so re-create the row
// for the survivor via store# (idempotent) and leave the disabled duplicate's row as-is;
// otherwise update in place. Auto-detecting the PK keeps this safe when new entities are added.
def _reparent = { entityName, field ->
    ec.entity.find(entityName).condition(field, mergedPartyId).list().each { row ->
        if (row.getPrimaryKeys().containsKey(field)) {
            def m = new HashMap(row); m[field] = survivingPartyId
            ec.service.sync().name("store#" + entityName).parameters(m).call()
        } else {
            row.set(field, survivingPartyId)
            row.update()
        }
    }
}
// Core transactional history
_reparent("mantle.order.OrderPart", "customerPartyId")
_reparent("mantle.order.OrderPart", "vendorPartyId")
_reparent("mantle.account.invoice.Invoice", "fromPartyId")
_reparent("mantle.account.invoice.Invoice", "toPartyId")
_reparent("mantle.account.payment.Payment", "fromPartyId")
_reparent("mantle.account.payment.Payment", "toPartyId")
_reparent("zenith.erp.pos.PosTransaction", "customerPartyId")
// Secondary customer records: shipments, subscriptions, loyalty, and customer balances
// (store credit, gift cards). ShipmentParty.partyId is in its PK — the helper detects that
// and re-creates the survivor's row rather than updating in place.
_reparent("mantle.shipment.Shipment", "fromPartyId")
_reparent("mantle.shipment.Shipment", "toPartyId")
_reparent("mantle.shipment.ShipmentParty", "partyId")
_reparent("zenith.erp.subscriptions.Subscription", "customerPartyId")
_reparent("zenith.erp.loyalty.LoyaltyMember", "partyId")
_reparent("zenith.erp.giftcard.StoreCredit", "partyId")
_reparent("zenith.erp.giftcard.GiftCard", "issuedToPartyId")
_reparent("zenith.erp.giftcard.GiftCard", "purchasedByPartyId")

import java.util.zip.ZipOutputStream import java.util.zip.ZipEntry
def esc = { v -> v == null ? '' : v.toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'","&apos;") }
int nCols = headers.size()
// 0-based column index -> Excel column letters (A, B, ... Z, AA, ...) def colLetter = { int idx -> StringBuilder sb = new StringBuilder() int n = idx while (n >= 0) { sb.insert(0, (char)(('A'.charAt(0)) + (n % 26))); n = ((int)(n / 26)) - 1 } return sb.toString() }
// Column widths from content (chars + padding), clamped 10..60. int[] widths = new int[nCols] for (int c = 0; c < nCols; c++) widths[c] = Math.max(10, ((headers[c] == null ? '' : headers[c].toString()).length() + 2)) for (row in rows) { for (int c = 0; c < nCols; c++) { def cell = (c < row.size()) ? row[c] : '' int len = ((cell == null ? '' : cell.toString()).length()) + 2 if (len > widths[c]) widths[c] = len } } for (int c = 0; c < nCols; c++) if (widths[c] > 60) widths[c] = 60
def baos = new ByteArrayOutputStream() def zos = new ZipOutputStream(baos) def addEntry = { name, content -> zos.putNextEntry(new ZipEntry(name)); zos.write(content.getBytes("UTF-8")); zos.closeEntry() }
addEntry("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"> <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/> <Default Extension="xml" ContentType="application/xml"/> <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/> <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/> <Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/> </Types>""")
addEntry("_rels/.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"> <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/> </Relationships>""")
// Excel sheet names: <=31 chars, none of : \ / ? * [ ] def safeSheet = (sheetName ?: 'Sheet1').toString().replaceAll('[\\\\/\\?\\*\\[\\]:]', ' ') if (safeSheet.length() > 31) safeSheet = safeSheet.substring(0, 31)
addEntry("xl/workbook.xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"> <sheets> <sheet name="${esc(safeSheet)}" sheetId="1" r:id="rId1"/> </sheets> </workbook>""")
addEntry("xl/_rels/workbook.xml.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"> <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/> <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/> </Relationships>""")
// Style 1 = header (bold white on indigo fill), matching the app's list header look. addEntry("xl/styles.xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"> <fonts count="2"> <font><name val="Calibri"/><sz val="11"/></font> <font><b/><color rgb="FFFFFFFF"/><name val="Calibri"/><sz val="11"/></font> </fonts> <fills count="2"> <fill><patternFill patternType="none"/></fill> <fill><patternFill patternType="solid"><fgColor rgb="FF1A237E"/><bgColor indexed="64"/></patternFill></fill> </fills> <borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders> <cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs> <cellXfs count="2"> <xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/> <xf numFmtId="0" fontId="1" fillId="1" borderId="0" xfId="0" applyFont="1" applyFill="1"/> </cellXfs> <cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles> </styleSheet>""")
def sx = new StringBuilder() sx.append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?> <worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"> <cols> """) for (int c = 0; c < nCols; c++) sx.append(""" <col min="${c+1}" max="${c+1}" width="${widths[c]}" customWidth="1"/>\n""") sx.append(""" </cols> <sheetData> <row r="1"> """) for (int c = 0; c < nCols; c++) { sx.append(""" <c r="${colLetter(c)}1" s="1" t="inlineStr"><is><t xml:space="preserve">${esc(headers[c])}</t></is></c>\n""") } sx.append(" </row>\n")
int rowIndex = 2 for (row in rows) { sx.append(""" <row r="${rowIndex}">\n""") for (int c = 0; c < nCols; c++) { def cell = (c < row.size()) ? row[c] : '' sx.append(""" <c r="${colLetter(c)}${rowIndex}" t="inlineStr"><is><t xml:space="preserve">${esc(cell)}</t></is></c>\n""") } sx.append(" </row>\n") rowIndex++ }
sx.append(""" </sheetData> </worksheet>""")
addEntry("xl/worksheets/sheet1.xml", sx.toString()) zos.close()
xlsxBase64 = baos.toByteArray().encodeBase64().toString()

def esc = { v ->
    def s = (v == null) ? '' : v.toString()
    if (s.indexOf('"') >= 0 || s.indexOf(',') >= 0 || s.indexOf('\n') >= 0 || s.indexOf('\r') >= 0) {
        s = '"' + s.replace('"', '""') + '"'
    }
    return s
}
int nCols = headers.size()
def sb = new StringBuilder()
sb.append((char) 0xFEFF)   // UTF-8 BOM -> Excel detects UTF-8
sb.append(headers.collect { esc(it) }.join(','))
sb.append('\r\n')
for (row in rows) {
    def cells = []
    for (int c = 0; c < nCols; c++) cells.add(esc((c < row.size()) ? row[c] : ''))
    sb.append(cells.join(','))
    sb.append('\r\n')
}
csvText = sb.toString()
